class Solution {
public:
    int rootCount(std::vector<std::vector<int>>& edges, std::vector<std::vector<int>>& guesses, int k) {
        int n = edges.size() + 1;
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        auto encode = [](long long u, long long v) -> long long {
            return (u << 32) | v;
        };
        std::unordered_set<long long> guess_set;
        for (const auto& g : guesses) {
            guess_set.insert(encode(g[0], g[1]));
        }
        int base_matches = 0;
        auto dfs1 = [&](auto& self, int u, int p) -> void {
            for (int v : adj[u]) {
                if (v != p) {
                    if (guess_set.count(encode(u, v))) {
                        base_matches++;
                    }
                    self(self, v, u);
                }
            }
        };
        dfs1(dfs1, 0, -1);
        int valid_roots = 0;
        auto dfs2 = [&](auto& self, int u, int p, int curr) -> void {
            if (curr >= k) valid_roots++;
            for (int v : adj[u]) {
                if (v != p) {
                    int next_m = curr;
                    if (guess_set.count(encode(u, v))) next_m--;
                    if (guess_set.count(encode(v, u))) next_m++;
                    self(self, v, u, next_m);
                }
            }
        };
        dfs2(dfs2, 0, -1, base_matches);
        return valid_roots;
    }
};

class Solution {
    private int baseMatches = 0;
    private int validRoots = 0;
    private java.util.Set<Long> guessSet = new java.util.HashSet<>();

    private long encode(long u, long v) {
        return (u << 32) | v;
    }

    public int rootCount(int[][] edges, int[][] guesses, int k) {
        int n = edges.length + 1;
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        for (int[] g : guesses) {
            guessSet.add(encode(g[0], g[1]));
        }
        dfs1(0, -1, adj);
        dfs2(0, -1, baseMatches, k, adj);
        return validRoots;
    }

    private void dfs1(int u, int p, java.util.List<Integer>[] adj) {
        for (int v : adj[u]) {
            if (v != p) {
                if (guessSet.contains(encode(u, v))) {
                    baseMatches++;
                }
                dfs1(v, u, adj);
            }
        }
    }

    private void dfs2(int u, int p, int curr, int k, java.util.List<Integer>[] adj) {
        if (curr >= k) validRoots++;
        for (int v : adj[u]) {
            if (v != p) {
                int nextM = curr;
                if (guessSet.contains(encode(u, v))) nextM--;
                if (guessSet.contains(encode(v, u))) nextM++;
                dfs2(v, u, nextM, k, adj);
            }
        }
    }
}

